 "content": "def transform(grid):
    """Recolor full-height/full-width separator lines to marker color 2."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    full_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    full_cols = {c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))}
    # Lines in this task share one separator color. Only recolor full lines;
    # intersections are naturally recolored as well.
    out = [row[:] for row in grid]
    for r in full_rows:
        out[r] = [2] * w
    for c in full_cols:
        for r in range(h):
            out[r][c] = 2
    return out
